const limit = Math.min(lim, 50);
const num = (v) => { const n = Number(v); return (isNaN(n) || v === null || v === undefined) ? 0 : n; };
const iso = (t) => {
  if (t === undefined || t === null || t === '') return null;
  const n = typeof t === 'number' ? t * 1000 : Date.parse(t);
  return isNaN(n) ? null : new Date(n).toISOString();
};
const resp = $input.first().json;

const raw = (resp && Array.isArray(resp.items)) ? resp.items : [];
const posts = raw.map((it) => {
  const cap = (it.caption && typeof it.caption === 'object') ? (it.caption.text || '') : (it.caption || '');
  return {
    id: String(it.id || it.code || ''),
    url: it.url || (it.code ? 'https://www.instagram.com/reel/' + it.code + '/' : ''),
    views: num(it.play_count),
    likes: num(it.like_count),
    comments: num(it.comment_count),
    shares: 0,
    posted_at: iso(it.taken_at),
    thumb_url: it.display_uri || null,
    duration: null
  };
}).filter((p) => p.id !== '');
posts.forEach((p) => {
  p.er = p.views > 0 ? Math.round(((p.likes + p.comments * 3 + p.shares * 5) / p.views) * 10000) / 10000 : 0;
});
posts.sort((a, b) => b.er - a.er);
const top = posts.slice(0, limit);
return [{ json: { ok: true, count: top.length, platform: 'instagram', handle: handle, posts: top } }];

